using Aspose.[identifier omitted];

// Load an STL file using format detection
var scene = new Scene();
var format = FileFormat.StlFormat();
scene.Open("input.stl", format.CreateLoadOptions());

// Assign PhongMaterial to the first node's entity
var node = scene.RootNode.ChildNodes[0];
var entity = node.Entity as Entity;
if (entity != null)
{
    entity.Material = new PhongMaterial() { DiffuseColor = new Vector3(0.8f, 0.2f, 0.2f) };
}

// Save as OBJ format
scene.Save("output.obj", FileFormat.ObjFormat().CreateSaveOptions());
